// COM exposes an eye midpoint only. Unsupported orientation/eyes/ears are NaN.
namespace {
SR_point3d UnknownPoint() {
    const double n=std::numeric_limits<double>::quiet_NaN();
    return {n,n,n};
}
SR_headPose PositionFrame(const titan::Snapshot& s,bool usable,uint64_t sequence) {
    SR_headPose frame{};frame.frameId=sequence;
    frame.position=frame.orientation=UnknownPoint();
    // A hold/default is valid for optical weaving, not a measured head position.
    const auto tick=GetTickCount64();
    if(!usable || s.eyePositionValid!=titan::kEyeTracked || !s.observationTick ||
        s.observationTick>tick || tick-s.observationTick>250)return frame;
    titan::render::OpticalConstants optical{};
    if(!titan::render::MakeOpticalConstants(s,1,1,2,1,optical)||optical.eyeZ<=0)return frame;
    // BOE's transformed display axes are +right/+up/+viewer (see original CS
    // pixel coordinates x-width/2, height/2-y). Units remain millimetres.
    frame.position={optical.eyeX,optical.eyeY,optical.eyeZ};
    // This is a local COM observation time, NEVER a camera exposure timestamp.
    FILETIME now{};GetSystemTimePreciseAsFileTime(&now);
    ULARGE_INTEGER ticks{};ticks.LowPart=now.dwLowDateTime;ticks.HighPart=now.dwHighDateTime;
    const uint64_t epochUs=(ticks.QuadPart-116444736000000000ULL)/10;
    const auto age=s.observationTick&&tick>=s.observationTick?tick-s.observationTick:0;
    frame.time=epochUs>age*1000?epochUs-age*1000:0;
    return frame;
}
