SR_headPose PositionFrame(const titan::Snapshot& s,bool usable,uint64_t sequence) {
    SR_headPose frame{};frame.frameId=sequence;
    frame.position=frame.orientation=UnknownPoint();
    // A hold/default is valid for optical weaving, not a measured head position.
    const auto tick=GetTickCount64();
    if(!usable || s.eyePositionValid!=titan::kEyeTracked || !s.observationTick ||
