void SRContext::startAllSenses() { FindContext(this)->started=true; for (auto& entry : senses) for (auto* sense : entry.second) sense->start(); }
void SRContext::stopAllSenses() {
    {std::lock_guard lock(contextMutex);const auto it=contexts.find(this);if(it!=contexts.end())it->second->started=false;}
