WeaverErrorCode CreateDX12Weaver(SRContext* context, ID3D12Device* device, HWND window, IDX12Weaver1** weaver) {
    if (!weaver) return WeaverTextureFailedToLoad;
    *weaver = nullptr;
    if (!context || !device) return WeaverTextureFailedToLoad;
    try {
        auto state = FindContext(context);
        titan::Snapshot snapshot{};
